#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, rank_;
    DSU(int n) : parent(n), rank_(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;
        if (rank_[x] < rank_[y]) swap(x, y);
        parent[y] = x;
        if (rank_[x] == rank_[y]) rank_[x]++;
    }
};

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<int> xs(n), ys(n);
    for(int i = 0; i < n; i++) cin >> xs[i] >> ys[i];

    // Compress coordinates
    vector<int> rx = xs, ry = ys;
    sort(rx.begin(), rx.end()); rx.erase(unique(rx.begin(), rx.end()), rx.end());
    sort(ry.begin(), ry.end()); ry.erase(unique(ry.begin(), ry.end()), ry.end());

    int R = rx.size(), C = ry.size();
    DSU dsu(R + C);

    for(int i = 0; i < n; i++){
        int r = lower_bound(rx.begin(), rx.end(), xs[i]) - rx.begin();
        int c = lower_bound(ry.begin(), ry.end(), ys[i]) - ry.begin();
        dsu.unite(r, R + c);
    }

    // For each component, count rows and columns
    map<int, pair<int,int>> comp; // root -> (row_count, col_count)
    for(int i = 0; i < R; i++){
        comp[dsu.find(i)].first++;
    }
    for(int j = 0; j < C; j++){
        comp[dsu.find(R + j)].second++;
    }

    long long total = 0;
    for(auto& [root, rc] : comp){
        total += (long long)rc.first * rc.second;
    }

    cout << total - n << endl;

    return 0;
}

