        byX[x].push_back(y);
    }

    // Coordinate compress y values
    set<int> ys;
    for (auto &p : byX) {
        for (int y : p.second) {
            ys.insert(y);
        }
    }
    map<int, int> yComp;
    int idx = 0;
    for (int y : ys) {
        yComp[y] = idx++;
    }
    int M = ys.size();

    // DSU for y coordinates
    vector<int> parent(M);
    iota(parent.begin(), parent.end(), 0);
    function<int(int)> find = [&](int u) {
        return parent[u] == u ? u : parent[u] = find(parent[u]);
    };
    auto unite = [&](int u, int v) {
        u = find(u);
        v = find(v);
        if (u != v) parent[u] = v;
    };

    // For each x, union all its y's
    for (auto &p : byX) {
        vector<int> &yvec = p.second;
        if (yvec.empty()) continue;
        int first = yComp[yvec[0]];
        for (int i = 1; i < (int)yvec.size(); i++) {
            unite(first, yComp[yvec[i]]);
        }
    }

    // Group x's by the root of their first y
    map<int, vector<int>> groups;
    for (auto &p : byX) {
        int root = find(yComp[p.second[0]]);
        groups[root].push_back(p.first);
    }

    long long totalPossible = 0;
    for (auto &g : groups) {
        int k = g.second.size();      // number of x's
        // Actually all y's in this component will be fully connected
        // So number of y's = component size
        int compRoot = g.first;
        int compSize = 0;
        for (int i = 0; i < M; i++) {
            if (find(i) == compRoot) compSize++;
        }
        // Total possible points = k * compSize
        // Already have some
        long long already = 0;
        for (int x : g.second) {
            already += byX[x].size();
        }
        totalPossible += (long long)k * compSize - already;
    }

    cout << totalPossible << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> xs(N), ys(N);
    for (int i = 0; i < N; ++i) cin >> xs[i] >> ys[i];

    // Compress x and y coordinates independently.
    vector<long long> ux = xs, uy = ys;
    sort(ux.begin(), ux.end());
    ux.erase(unique(ux.begin(), ux.end()), ux.end());
    sort(uy.begin(), uy.end());
    uy.erase(unique(uy.begin(), uy.end()), uy.end());

    int X = (int)ux.size();
    int Y = (int)uy.size();

    vector<vector<int>> adjX(X), adjY(Y);
    vector<vector<char>> has(X, vector<char>(Y, 0));

    for (int i = 0; i < N; ++i) {
        int xi = lower_bound(ux.begin(), ux.end(), xs[i]) - ux.begin();
        int yi = lower_bound(uy.begin(), uy.end(), ys[i]) - uy.begin();
        if (!has[xi][yi]) {
            has[xi][yi] = 1;
            adjX[xi].push_back(yi);
            adjY[yi].push_back(xi);
        }
    }

    // Build bipartite graph:
    // left side = distinct x-values, right side = distinct y-values,
    // edge exists iff point (x, y) is present.
    //
    // Operation adds one missing corner of a rectangle. Repeating until impossible
    // fills each connected component of this bipartite graph into a complete
    // bipartite graph. Therefore maximum additions in a component are:
    // (#x in comp) * (#y in comp) - (#existing edges in comp)
    // Summed over all components.
    //
    // Since every original edge belongs to exactly one component, total answer is:
    // sum over components (#x_comp * #y_comp) - N

    vector<char> visX(X, 0), visY(Y, 0);
    long long ans = 0;

    for (int sx = 0; sx < X; ++sx) {
        if (visX[sx]) continue;

        queue<pair<int,int>> q; // {type, id}, type 0=x, 1=y
        q.push({0, sx});
        visX[sx] = 1;

        long long cntX = 0, cntY = 0, edges = 0;

        while (!q.empty()) {
            auto [tp, v] = q.front();
            q.pop();

            if (tp == 0) {
                cntX++;
                edges += (long long)adjX[v].size();
                for (int y : adjX[v]) {
                    if (!visY[y]) {
                        visY[y] = 1;
                        q.push({1, y});
                    }
                }
            } else {
                cntY++;
                for (int x : adjY[v]) {
                    if (!visX[x]) {
                        visX[x] = 1;
                        q.push({0, x});
                    }
                }
            }
        }

        ans += cntX * cntY - edges;
    }

    cout << ans << '\n';
    return 0;
}

