            ys[i] = Integer.parseInt(st.nextToken());
        }

        // Coordinate compression
        int[] uxs = xs.clone(); Arrays.sort(uxs); uxs = Arrays.stream(uxs).distinct().toArray();
        int[] uys = ys.clone(); Arrays.sort(uys); uys = Arrays.stream(uys).distinct().toArray();
        int R = uxs.length, C = uys.length;

        parent = new int[R + C];
        rank = new int[R + C];
        for (int i = 0; i < R + C; i++) parent[i] = i;

        for (int i = 0; i < N; i++) {
            int r = Arrays.binarySearch(uxs, xs[i]);
            int c = Arrays.binarySearch(uys, ys[i]);
