public class Main {
    static class DSU {
        int[] parent, sizeR, sizeC;

        DSU(int n) {
            parent = new int[n];
            sizeR = new int[n];
            sizeC = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                sizeR[i] = 0;
                sizeC[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (sizeR[ra] + sizeC[ra] < sizeR[rb] + sizeC[rb]) {
                int tmp = ra; ra = rb; rb = tmp;
            }
            parent[rb] = ra;
            sizeR[ra] += sizeR[rb];
            sizeC[ra] += sizeC[rb];
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());

        int[] xs = new int[N];
        int[] ys = new int[N];

        // coordinate compression
        Set<Integer> xSet = new HashSet<>();
        Set<Integer> ySet = new HashSet<>();
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            xs[i] = Integer.parseInt(st.nextToken());
            ys[i] = Integer.parseInt(st.nextToken());
            xSet.add(xs[i]);
            ySet.add(ys[i]);
        }

        // map rows and columns to contiguous indices
        Map<Integer, Integer> xMap = new HashMap<>();
        Map<Integer, Integer> yMap = new HashMap<>();
        int idx = 0;
        for (int x : xSet) xMap.put(x, idx++);
        int rowCount = idx;
        for (int y : ySet) yMap.put(y, idx++);
        int totalNodes = idx;

        DSU dsu = new DSU(totalNodes);
        // mark row and column counts
        for (int x : xSet) {
            int id = xMap.get(x);
            dsu.sizeR[dsu.find(id)]++;
        }
        for (int y : ySet) {
            int id = yMap.get(y);
            dsu.sizeC[dsu.find(id)]++;
        }

        // union each dot's row and column
        for (int i = 0; i < N; i++) {
            int r = xMap.get(xs[i]);
            int c = yMap.get(ys[i]);
            dsu.union(r, c);
        }

        // sum possible edges in each component
        boolean[] visited = new boolean[totalNodes];
        long totalPossible = 0;
        for (int i = 0; i < totalNodes; i++) {
            int root = dsu.find(i);
            if (!visited[root]) {
                visited[root] = true;
                long rows = dsu.sizeR[root];
                long cols = dsu.sizeC[root];
                totalPossible += rows * cols;
            }
        }

        System.out.println(totalPossible - N);
    }
}

